@Override
public void visitReference(@NotNull JavaContext context, @NotNull UReferenceExpression reference, @NotNull PsiElement referenced) {
    if (!isOldExif(referenced)) return;
    UElement parent = reference.getUastParent();
    if (parent instanceof UCallExpression) {
        UCallExpression call = (UCallExpression) parent;
        if (call.getKind() == UastCallKind.CONSTRUCTOR_CALL) {
            return;
        }
    }
    // skip if inside import statement
    UElement p = reference;
    while (p != null) {
        if (p instanceof UImportStatement) return;
        p = p.getUastParent();
    }
    context.report(ISSUE, reference, context.getLocation(reference), MESSAGE);
}
